// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2003, "3-5", [{"author":"М. Кронгауз","question":"Ваня шёл по деревне и встретил каких-то животных. От испуга он забыл, как они называются. Когда мама спросила, много ли их было, Ваня ответил: «Очень! Целый табун!». Мама сразу догадалась, что это были:","choices":["лошади","собаки","гуси","коровы","овцы"],"key":"А","review":["Табун и другие группы","У групп животных бывают разные названия. Например, овцы собираются в отару, а собаки — в стаю.","Табуном называют группу лошадей. По этому слову мама узнала животных."]},{"author":"М. Кронгауз","question":"Петя научился приветствовать знакомых разными способами, но всегда делает это невпопад: учителю машет рукой, маме отдаёт честь, другу сдержанно кивает. Научите его, кому при встрече принято пожимать руку:","choices":["учителю","маме","знакомой девушке","другу","другу и маме"],"key":"Г","review":["Рукопожатие при встрече","В этом разговоре нужно выбрать обычное приветствие для близкого знакомого.","Пожать руку принято при встрече с другом. Отдавать честь здесь незачем: это военное приветствие."]},{"author":"И. Рубанов","question":"Знаете ли вы, что ГРАБ — это дерево, родственное берёзе? Уже знаете? Тогда скажите, сколько осмысленных русских слов можно получить, заменяя в слове ГРАБ букву А другой буквой?","choices":["1","2","3","4","5"],"key":"Г","review":["Одна гласная меняется","В «ГРАБ» оставь Г, Р и Б на своих местах. О даёт «гроб», И — «гриб».","У даёт краткое прилагательное «груб», а Ё — глагольную форму «грёб». Получаются четыре слова."]},{"author":"Н. Валеева","question":"Какое из этих слов по смыслу лишнее?","choices":["волкодав","борзая","пудель","собака","овчарка"],"key":"Г","review":["Название группы и её члены","Волкодав, борзая, пудель и овчарка — названия собак определённых пород или типов.","«Собака» — общее название для всех них. Поэтому оно выделяется по смыслу."]},{"author":"И. Рубанов","question":"У меня зазвонил …","choices":["тилифон","телефон","тилефон","телифон","среди ответов (А)–(Г) нет правильного"],"key":"Б","review":["Как пишется «телефон»","Слышны безударные гласные, которые легко принять за и.","В слове «телефон» в обоих первых слогах пишется е. Этот вариант и завершает строку."]},{"author":"М. Кронгауз","question":"Я положил в сумку: надувной матрас, плавки, полотенце, книжку, кастрюлю. Угадайте, куда я собрался, если одну вещь я взял по ошибке.","choices":["в гости","в школу","на пляж","в бассейн","в кино"],"key":"В","review":["Что взяли к воде","Плавки, полотенце и надувной матрас нужны для купания. Книжку можно читать, отдыхая у воды.","С этими вещами собираются на пляж. Кастрюля здесь лишняя."]},{"author":"М. Кронгауз","question":"— У меня дома завелись, тьфу, забыл, как называются.\n— Насекомые?\n— Да.\n— Ползают?\n— Да.\n— Страшные?\n— Очень.\n— Кусаются?\n— Нет.\n— С усами?\n— Вроде да.\n—Так это же:","choices":["змеи","тараканы","муравьи","клопы","мухи"],"key":"Б","review":["Усатые насекомые дома","Змея не насекомое, а муха обычно летает. Клопы известны тем, что кусают людей.","Привычный домашний вредитель, который ползает и имеет длинные усы, — таракан."]},{"author":"Л. Фёдорова","question":"По сообщениям газет, один японский рыбак выловил на удочку «чудо-юдо» — молодого осьминога с 28 щупальцами! А сколько их обычно бывает у этого обитателя морских глубин?","choices":["4","5","6","8","40"],"key":"Г","review":["Название с числом","Слово «осьминог» связано со старым «осемь» — восемь. Вторая часть напоминает о ногах.","У обычного осьминога восемь рук. На необычный экземпляр с 28 указывает само условие."]},{"author":"Е. Муравенко","question":"Почти из всех этих существительных можно убрать по одной букве так, что получатся числительные. Только из одного числительное так не получается. Из какого?","choices":["сорока","семя","сито","шерсть","дева"],"key":"Б","review":["Убираем одну букву","Из «сорока» без а получается «сорок», из «сито» без и — «сто». «Шерсть» без р даёт «шесть», «дева» без е — «два».","Из «семя» так не получить «семь»: нужно заменить я на ь. Поэтому выделяется «семя»."]},{"author":"И. Иткин","question":"Вы, конечно, видите, что эти пять слов оканчиваются одинаково. Но по составу одно из них отличается от остальных. Найдите его.","choices":["рыбак","дурак","простак","чужак","казак"],"key":"Д","review":["Что входит в корень","«Рыбак» связано с «рыба», «дурак» — с «дурной», «простак» — с «простой», «чужак» — с «чужой». В них выделяется -ак.","У слова «казак» сочетание -ак входит в корень, а не присоединяется к другой основе."]},{"author":"М. Кронгауз","question":"Студент позвонил маме: «Денег осталось очень мало, ну просто кот …». Тут связь прервалась. Какое слово мама не услышала?","choices":["намяукал","намурлыкал","насмеялся","наурчал","наплакал"],"key":"Д","review":["Денег почти нет","Выражение «кот наплакал» означает «очень мало».","Студент начал известный оборот, поэтому мама могла догадаться, что связь оборвалась перед словом «наплакал»."]},{"author":"И. Иткин","question":"Какое по счёту место занимает в русском алфавите последняя из согласных букв?","choices":["24","26","27","29","30"],"key":"В","review":["Последняя согласная в ряду","Последняя согласная — щ. После неё идут ъ, ы, ь, э, ю, я: знаки и гласные буквы.","Этих букв шесть. Во всём алфавите 33 буквы, значит щ стоит на 27-м месте."]},{"author":"И. Рубанов","question":"В каких из этих слов пишется два р: ко...идор, ко...еспондент, ко...алл?","choices":["только в первом","в первом и втором","только во втором","во втором и третьем","во всех трёх"],"key":"В","review":["Проверяем три написания","В пропуске в «коридор» и «коралл» пишется одна р. У «коралл» удваивается л в конце.","Два р подряд есть в слове «корреспондент». Это второй вариант в списке."]},{"author":"И. Иткин","question":"Сложносокращённым называется слово, составленное из двух других, причем одно или оба исходных слова частично урезаются. Например: универмаг = универ[сальный] + маг[азин], спецзадание = спец[иальное] + задание. Какое из следующих пяти слов — не сложносокращённое?","choices":["турпоход","турслёт","турагентство","турникет","физкультура"],"key":"Г","review":["Как устроено сложное слово","Турпоход, турслёт и турагентство содержат сокращённую часть от «туристический», а физкультура — от «физический».","В слове «турникет» такой сокращённой части нет. Это целиком заимствованное слово."]},{"author":"Е. Дмитриева","question":"В каком случае перенос ударения не меняет значения слова?","choices":["и́рис — ири́с","кле́щи — клещи́","а́тлас — атла́с","мо́лодец — молоде́ц","тво́рог — творо́г"],"key":"Д","review":["Два ударения, один продукт","Ударение различает «и́рис» и «ири́с», «кле́щи» и «клещи́», «а́тлас» и «атла́с», «мо́лодец» и «молоде́ц».","«Тво́рог» и «творо́г» обозначают один и тот же молочный продукт. Допустимы оба ударения."]},{"author":"Е. Муравенко","question":"Что обычно не кладут в портфель?","choices":["Ребус А","Ребус Б","Ребус В","Ребус Г","Ребус Д"],"key":"Г","review":["Пять вещей из ребусов","В ребусах скрыты тетрадь, линейка, пенал, подушка и дневник. Четыре предмета обычно нужны школьнику.","В ребусе Г У по Д, а у шкафа убирается последняя ф: «по-Д-У-шка». Подушку обычно не носят в портфеле."],"figure":{"options":[{"src":"assets/medvezhonok/2003/3-5-16-rebus-1.webp","description":"Буква Т, число 100 см и гиря с запятыми.","pixelWidth":161,"pixelHeight":50},{"src":"assets/medvezhonok/2003/3-5-16-rebus-2.webp","description":"Лист, буква Н и лейка с запятыми.","pixelWidth":190,"pixelHeight":52},{"src":"assets/medvezhonok/2003/3-5-16-rebus-3.webp","description":"Курсивная буква и фигура из двух букв.","pixelWidth":74,"pixelHeight":55},{"src":"assets/medvezhonok/2003/3-5-16-rebus-4.webp","description":"Большая Д в маленьких У и шкаф с запятой справа.","pixelWidth":185,"pixelHeight":64},{"src":"assets/medvezhonok/2003/3-5-16-rebus-5.webp","description":"Единица рядом с веником и обозначение перестановки.","pixelWidth":129,"pixelHeight":62}]}},{"author":"Н. Валеева","question":"В какие слова вместо многоточия нужно вставить букву ы (а не и): 1) камыш..., 2) ж...раф, 3) ножниц..., 4) верш...на, 5) мотоц...кл?","choices":["в 1, 2 и 4","в 1 и 3","в 3 и 5","в 3","во всех этих словах пропущена буква и"],"key":"Г","review":["Где пишется «ы»","В словах «камыши», «жираф», «вершина» после шипящих пишется и. «Мотоцикл» также пишется с и.","«Ножницы» имеют окончание -ы после ц. Это единственный такой случай в предложенном списке."]},{"author":"И. Иткин","question":"Догадайтесь, какой русский писатель иногда подписывал свои произведения псевдонимом Нави Волырк:","choices":["Денис Иванович Фонвизин","Иван Андреевич Крылов","Александр Сергеевич Грибоедов","Александр Сергеевич Пушкин","Николай Васильевич Гоголь"],"key":"Б","review":["Псевдоним наоборот","Прочитай обе части подписи справа налево, сохраняя их места.","«Нави» превратится в «Иван», «Волырк» — в «Крылов». Это Иван Андреевич Крылов."]},{"author":"Е. Дмитриева","question":"Каждым из этих слов можно назвать низкорослого человека. Но только одно из них является названием реально существующей народности. Какое?","choices":["карлик","лилипут","гном","пигмей","коротышка"],"key":"Г","review":["Название народов","«Гном» и «лилипут» происходят из сказок или вымысла, «коротышка» и «карлик» описывают рост.","«Пигмеи» — историческое собирательное название нескольких реально существующих групп народов с невысоким средним ростом."]},{"author":"М. Кронгауз","question":"По имени человека часто можно определить, к какой культуре и нации он относится. Например, сказка про Ивана — русская. Мне попалась народная сказка, где главного героя звали Джузеппе. Какая это была сказка?","choices":["шведская","французская","чешская","итальянская","испанская"],"key":"Г","review":["Откуда имя Джузеппе","Джузеппе — итальянская форма имени Иосиф. Итальянское происхождение выдаёт звучание имени.","Значит, в задании речь об итальянской народной сказке."]},{"author":"Е. Дмитриева","question":"В каком из слов количество букв не совпадает с количеством звуков?","choices":["объект","июнь","майор","бульон","ящик"],"key":"Д","review":["Буквы и звуки в «ящик»","В начале слова буква я передаёт [й’] и [а]. В «ящик» четыре буквы, но пять звуков.","В других вариантах звук [й’] у е, ю или о компенсируется тем, что ъ или ь отдельного звука не передаёт. В «майор» й обозначен отдельной буквой. Там число букв и звуков совпадает."]},{"author":"Е. Дмитриева","question":"Редактор газеты отчего-то очень не любит слово пытаться. Подскажите репортёру, каким из пяти слов он может заменить в своей заметке это слово, чтобы смысл сказанного не изменился:","choices":["пробовать","изощряться","надеяться","усердствовать","надрываться"],"key":"А","review":["Сделать попытку","«Пытаться что-то сделать» — предпринимать попытку, даже если результат пока неизвестен.","«Пробовать что-то сделать» сохраняет тот же смысл. Например, «пытался открыть дверь» и «пробовал открыть дверь»."]},{"author":"И. Рубанов","question":"Гра́вер за гра́вюру гро́ша досто́ин.\nНесём из мага́зина в по́ртфеле медь.\nМо́жет быть, сти́хи писа́ть не сто́ит,\nА лу́чше в библио́теке со сло́варем посиде́ть?\nВот такая сатира на безграмотные стихи была опубликована однажды в студенческой стенгазете. А сколько ударений здесь поставлено неверно?","choices":["4","5","6","8","9"],"key":"Г","review":["Проверяем ударения в стихе","В первых двух строках нужны «гравёр», «гравю́ру», «гроша́», «магази́на» и «портфе́ле». Это пять исправлений.","Дальше исправляем «стихи́», «библиоте́ке» и «словарём»: ещё три. Всего восемь."]},{"author":"Е. Муравенко","question":"Некоторые русские словосочетания имеют, кроме прямого, ещё и общепринятый переносный смысл. Например, когда говорят, что Петя с Васей вместе пуд соли съели, то обычно имеется в виду не то, что Петя и Вася совместно употребили 16 кг соли, а то, что они давно и хорошо знакомы. У четырёх из пяти приведённых ниже словосочетаний есть переносный смысл, а у одного — нет. У какого?","choices":["обвести вокруг пальца","смотреть сквозь пальцы","пальцем не шевельнуть","согнуть палец","высосать из пальца"],"key":"Г","review":["Буквальное действие пальцем","«Обвести вокруг пальца» — обмануть; «смотреть сквозь пальцы» — намеренно не замечать; «пальцем не шевельнуть» — не приложить усилий; «высосать из пальца» — придумать без оснований.","«Согнуть палец» обычно означает буквальное движение. Общеизвестного переносного смысла здесь нет."]},{"author":"Н. Муравенко","question":"Даны глаголы: 1) сидит, 2) лежит, 3) висит, 4) идёт. Какие из них можно использовать как сказуемое, если подлежащим будет слово платье?","choices":["все","все, кроме 1","все, кроме 2","все, кроме 4","2 и 3"],"key":"А","review":["Четыре действия платья","Платье может сидеть по фигуре, лежать на полке или висеть на вешалке.","Фраза «это платье ей идёт» означает, что оно ей к лицу. Подходят все четыре глагола."]},{"author":"К. Кноп","question":"Что триста лет назад означало слово виктория?","choices":["госпожа","удача","чужбина","разлука","победа"],"key":"Д","review":["Старинное слово о победе","«Виктория» пришло из латинского victoria — «победа».","Когда в старинном тексте говорят «одержать викторию», это значит «одержать победу»."]},{"author":"Е. Дмитриева","question":"Когда возникают новые вещи, старые слова порой приобретают новые значения. Ниже приведены пять примеров таких новых значений. Одно из них соотносится со старым значением того же слова не так, как остальные четыре. Какое?","choices":["диск (со звукозаписью)","хворост (кондитерское изделие)","дипломат (чемоданчик)","хвост (очереди)","крыло (самолёта)"],"key":"В","review":["Сходство или назначение","Диск похож на плоский круг, хворост — на веточки, хвост очереди — на продолжение сзади, крыло самолёта — на крыло птицы.","Чемоданчик «дипломат» назван по связи с теми, кто мог его носить, а не по внешнему сходству с человеком."]},{"author":"Н. Валеева","question":"Посмотрите на слова аппетит, мозги, нежности, холод и решите, кто лишний:","choices":["собака","кошка","волк","телёнок","курица"],"key":"Б","review":["Прилагательные от животных","Есть выражения «волчий аппетит», «куриные мозги», «телячьи нежности» и «собачий холод».","Кошку ни с одним из этих существительных так обычно не связывают. Она лишняя."]},{"author":"П. Аркадьев","question":"Даны венгерские слова и их переводы на русский язык:\nkorsó — кувшин, korsóba — в кувшин, házból — из дома, asztalba — в стол, ház — дом (знак ударения здесь обозначает долготу гласной). \nКак будет по-венгерски: стол, из кувшина, в дом?","choices":["asztal, korsóba, háza","asztalb, korsóból, ház","asztal, korsóból, hazból","asztal, korsóból, hazbá","asztal, korsóból, házba"],"key":"Д","review":["Окончания направления","В примерах -ba значит «в», а -ból — «из». Убрав -ba из asztalba, получаем asztal — «стол».","К korsó добавляем -ból, к ház добавляем -ba. Получается asztal, korsóból, házba."]},{"author":"И. Рубанов","question":"В «Записках старого петербуржца» Льва Успенского упоминается магазин «Удивительно всё дёшево», где каждая вещь стоила ровно полтинник. «По правде сказать, не стоила она и четвертака», — писал Успенский. Во сколько же раз, по мнению писателя, хозяин магазина завышал цены?","choices":["менее чем в два","в два","более чем в два","по крайней мере, в три","более чем в четыре"],"key":"В","review":["Сравнение старых монет","Полтинник — 50 копеек, четвертак — 25. Полтинник вдвое больше четвертака.","Вещь, по словам автора, не стоила даже 25 копеек. Значит, цену завышали более чем вдвое."]}], {"year":2003,"grade":"3-5","tasksFile":"3-5.pdf","answersFile":"3-5-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2003.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
